window.S02E04_FULL = {"show": "Young Sheldon", "season": 2, "episode": 4, "title": "A Financial Secret and Fish Sauce", "source": "https://sheldon-kuraj-bambey.net/238-subtitles/2-season/4-episode", "entries": [{"id": 1, "start": "00:00:01,479", "end": "00:00:03,319", "text": "For most students the weekend", "textRu": "Для большинства студентов выходные"}, {"id": 2, "start": "00:00:03,369", "end": "00:00:05,046", "text": "represented two days of fun,", "textRu": "представлял собой два дня веселья,"}, {"id": 3, "start": "00:00:05,124", "end": "00:00:07,715", "text": "freedom, and in the case of my brother", "textRu": "свободу, а в случае с моим братом"}, {"id": 4, "start": "00:00:07,793", "end": "00:00:10,644", "text": "a chance to ignore all forms of hygiene.", "textRu": "шанс игнорировать все формы гигиены."}, {"id": 5, "start": "00:00:13,320", "end": "00:00:15,262", "text": "Come on! Come on!", "textRu": "Ну давай же! Ну давай же!"}, {"id": 6, "start": "00:00:15,385", "end": "00:00:17,320", "text": "To me however it represented...", "textRu": "Однако для меня это представляло..."}, {"id": 7, "start": "00:00:17,398", "end": "00:00:19,801", "text": "An unwelcome break from education.", "textRu": "Нежелательный перерыв в учебе."}, {"id": 8, "start": "00:00:23,432", "end": "00:00:25,582", "text": "Whoo! Thank the Lord!", "textRu": "Ууу! Слава Господу!"}, {"id": 9, "start": "00:00:25,759", "end": "00:00:28,065", "text": "But this wasn't a typical weekend", "textRu": "Но это были не типичные выходные"}, {"id": 10, "start": "00:00:28,143", "end": "00:00:29,975", "text": "because this was the weekend", "textRu": "потому что это были выходные"}, {"id": 11, "start": "00:00:30,053", "end": "00:00:32,027", "text": "I got to do my parents taxes.", "textRu": "Я должен платить налоги родителям."}, {"id": 12, "start": "00:00:32,173", "end": "00:00:35,735", "text": "Howdy do, W-2.", "textRu": "Привет, W-2."}, {"id": 13, "start": "00:00:35,813", "end": "00:00:39,058", "text": "♪ Nobody else is stronger than I am ♪", "textRu": "♪ Никто не сильнее меня ♪"}, {"id": 14, "start": "00:00:39,136", "end": "00:00:41,727", "text": "♪ Yesterday I moved a mountain ♪", "textRu": "♪ Вчера я сдвинул гору ♪"}, {"id": 15, "start": "00:00:41,805", "end": "00:00:44,528", "text": "♪ I bet I could be your hero ♪", "textRu": "♪ Держу пари, я мог бы стать твоим героем ♪"}, {"id": 16, "start": "00:00:44,606", "end": "00:00:47,690", "text": "♪ I am a mighty little man ♪", "textRu": "♪ Я могучий маленький человек ♪"}, {"id": 19, "start": "00:00:57,072", "end": "00:00:59,364", "text": "\"If you were not covered by retirement plan", "textRu": "«Если вы не были застрахованы пенсионным планом"}, {"id": 20, "start": "00:00:59,442", "end": "00:01:00,841", "text": "but your spouse was,", "textRu": "но твой супруг был,"}, {"id": 21, "start": "00:01:00,919", "end": "00:01:03,269", "text": "see the worksheet on page14\"", "textRu": "см. рабочий лист на странице 14\""}, {"id": 22, "start": "00:01:03,566", "end": "00:01:05,152", "text": "Try and stop me.", "textRu": "Попробуй остановить меня."}, {"id": 23, "start": "00:01:06,378", "end": "00:01:08,552", "text": "Mom, I was going through our expenditures", "textRu": "Мам, я перечислял наши расходы"}, {"id": 24, "start": "00:01:08,630", "end": "00:01:10,739", "text": "and noticed our grocery bills are up 12%", "textRu": "и заметил, что наши счета за продукты выросли на 12 %."}, {"id": 25, "start": "00:01:10,817", "end": "00:01:13,300", "text": "compared to last quarter. Any idea why?", "textRu": "по сравнению с прошлым кварталом. Есть идеи, почему?"}, {"id": 26, "start": "00:01:13,588", "end": "00:01:16,357", "text": "There's a person at the end of the table that eats for free.", "textRu": "В конце стола сидит человек, который ест бесплатно."}, {"id": 27, "start": "00:01:16,435", "end": "00:01:18,723", "text": "There's a person at the other end of the table", "textRu": "На другом конце стола человек"}, {"id": 28, "start": "00:01:18,801", "end": "00:01:20,319", "text": "that eats for three.", "textRu": "который ест за троих."}, {"id": 29, "start": "00:01:21,541", "end": "00:01:24,098", "text": "I've been buying groceries for the church food drive.", "textRu": "Я покупала продукты для церковной продовольственной акции."}, {"id": 30, "start": "00:01:24,176", "end": "00:01:25,179", "text": "I think that's it.", "textRu": "Я думаю, это все."}, {"id": 31, "start": "00:01:25,257", "end": "00:01:27,098", "text": "Ooh, I bet I could write that off,", "textRu": "Ох, держу пари, я мог бы списать это со счетов,"}, {"id": 32, "start": "00:01:27,176", "end": "00:01:28,260", "text": "including the gas", "textRu": "включая газ"}, {"id": 33, "start": "00:01:28,338", "end": "00:01:30,098", "text": "it took to drive to the grocery store", "textRu": "потребовалось съездить в продуктовый магазин"}, {"id": 34, "start": "00:01:30,176", "end": "00:01:31,463", "text": "and then to the church.", "textRu": "а потом в церковь."}, {"id": 35, "start": "00:01:31,541", "end": "00:01:33,083", "text": "With all that driving, maybe she can count", "textRu": "Со всей этой ездой, возможно, она сможет рассчитывать"}, {"id": 36, "start": "00:01:33,161", "end": "00:01:34,494", "text": "her car as a home office.", "textRu": "ее машина как домашний офис."}, {"id": 37, "start": "00:01:34,572", "end": "00:01:35,778", "text": "Sounds aggressive, but I", "textRu": "Звучит агрессивно, но я"}, {"id": 38, "start": "00:01:35,856", "end": "00:01:37,426", "text": "like how you're thinking.", "textRu": "например, как ты думаешь."}, {"id": 39, "start": "00:01:37,604", "end": "00:01:39,967", "text": "None of that is necessary, it's for charity.", "textRu": "Ничего из этого не нужно, это на благотворительность."}, {"id": 40, "start": "00:01:40,045", "end": "00:01:41,313", "text": "What's the point of charity", "textRu": "В чем смысл благотворительности"}, {"id": 41, "start": "00:01:41,391", "end": "00:01:42,956", "text": "if there are no tax benefits?", "textRu": "если нет налоговых льгот?"}, {"id": 42, "start": "00:01:43,244", "end": "00:01:44,322", "text": "Eat your peas.", "textRu": "Ешьте свой горох."}, {"id": 43, "start": "00:01:44,400", "end": "00:01:45,848", "text": "I like how he's thinking.", "textRu": "Мне нравится, как он думает."}, {"id": 44, "start": "00:01:45,926", "end": "00:01:47,769", "text": "You eat your peas, too.", "textRu": "Ты тоже ешь свой горох."}, {"id": 45, "start": "00:01:51,822", "end": "00:01:53,385", "text": "Dad, banking question.", "textRu": "Папа, банковский вопрос."}, {"id": 46, "start": "00:01:53,463", "end": "00:01:54,486", "text": "What's that, buddy?", "textRu": "Что это, приятель?"}, {"id": 47, "start": "00:01:54,564", "end": "00:01:56,215", "text": "I noticed there's a check missing.", "textRu": "Я заметил, что чека не хватает."}, {"id": 48, "start": "00:01:56,293", "end": "00:01:57,957", "text": "I have a copy of check 128", "textRu": "У меня есть копия чека 128."}, {"id": 49, "start": "00:01:58,035", "end": "00:02:01,362", "text": "and a copy of check 130, but 129 isn't there.", "textRu": "и копия чека 130, а 129 там нет."}, {"id": 50, "start": "00:02:01,618", "end": "00:02:03,650", "text": "Oh, yeah, don't worry about it.", "textRu": "О да, не волнуйся об этом."}, {"id": 51, "start": "00:02:03,728", "end": "00:02:04,980", "text": "But I enjoy worrying;", "textRu": "Но мне нравится беспокоиться;"}, {"id": 52, "start": "00:02:05,058", "end": "00:02:06,659", "text": "I find it very relaxing.", "textRu": "Я нахожу это очень расслабляющим."}, {"id": 53, "start": "00:02:06,900", "end": "00:02:07,947", "text": "'Course you do.", "textRu": "Конечно, да."}, {"id": 54, "start": "00:02:08,025", "end": "00:02:09,543", "text": "I balanced the rest of the account,", "textRu": "Я сбалансировал остальную часть счета,"}, {"id": 55, "start": "00:02:09,621", "end": "00:02:12,173", "text": "and it appears to be a check for $300.", "textRu": "и это, кажется, чек на 300 долларов."}, {"id": 56, "start": "00:02:12,251", "end": "00:02:14,629", "text": "All right, well, let's just put it down", "textRu": "Хорошо, ну, давай просто оставим это"}, {"id": 57, "start": "00:02:14,707", "end": "00:02:16,815", "text": "for $300 for miscellaneous.", "textRu": "за 300 долларов за разное."}, {"id": 58, "start": "00:02:17,275", "end": "00:02:19,967", "text": "I've never labeled anything miscellaneous in my life.", "textRu": "Я никогда в жизни не навешивал ярлыков на что-то разное."}, {"id": 59, "start": "00:02:20,045", "end": "00:02:21,202", "text": "I'll go ask Mom.", "textRu": "Я пойду спрошу маму."}, {"id": 60, "start": "00:02:21,280", "end": "00:02:22,423", "text": "Wait.", "textRu": "Ждать."}, {"id": 61, "start": "00:02:23,759", "end": "00:02:25,448", "text": "I just remembered.", "textRu": "Я только что вспомнил."}, {"id": 62, "start": "00:02:27,392", "end": "00:02:29,277", "text": "I gave the money to a friend.", "textRu": "Я отдал деньги другу."}, {"id": 63, "start": "00:02:29,355", "end": "00:02:31,283", "text": "- Who? - It doesn't matter who.", "textRu": "- ВОЗ? - Неважно, кто."}, {"id": 64, "start": "00:02:31,361", "end": "00:02:32,449", "text": "Why'd you give it to them?", "textRu": "Зачем ты им это дал?"}, {"id": 65, "start": "00:02:32,527", "end": "00:02:35,159", "text": "They needed it. It... it's like charity.", "textRu": "Им это было нужно. Это... это как благотворительность."}, {"id": 66, "start": "00:02:35,407", "end": "00:02:37,488", "text": "Ooh, another write-off, excellent.", "textRu": "Ох, еще одно списание, отлично."}, {"id": 67, "start": "00:02:37,566", "end": "00:02:39,018", "text": "Hey. Hey, hey, hey.", "textRu": "Привет. Эй, эй, эй."}, {"id": 68, "start": "00:02:41,759", "end": "00:02:44,596", "text": "What do you say, we keep this quiet?", "textRu": "Что скажешь, мы держим это в тайне?"}, {"id": 69, "start": "00:02:44,947", "end": "00:02:46,384", "text": "You mean like a secret?", "textRu": "Ты имеешь в виду как секрет?"}, {"id": 70, "start": "00:02:46,462", "end": "00:02:49,300", "text": "No, no, just, you know, something between you and me.", "textRu": "Нет, нет, просто, знаешь, что-то между тобой и мной."}, {"id": 71, "start": "00:02:49,378", "end": "00:02:50,525", "text": "What about Mom?", "textRu": "А что насчет мамы?"}, {"id": 72, "start": "00:02:50,603", "end": "00:02:52,415", "text": "Mom is on a need-to-know basis.", "textRu": "Мама в порядке служебной необходимости."}, {"id": 73, "start": "00:02:52,493", "end": "00:02:55,424", "text": "- What if Mom needs to know? - Okay, it's a secret.", "textRu": "- А что, если маме нужно знать? - Хорошо, это секрет."}, {"id": 74, "start": "00:02:55,774", "end": "00:02:56,932", "text": "Just trust me.", "textRu": "Просто поверь мне."}, {"id": 75, "start": "00:02:57,010", "end": "00:02:59,743", "text": "It is better for everyone if she doesn't know about this.", "textRu": "Для всех будет лучше, если она об этом не узнает."}, {"id": 76, "start": "00:02:59,821", "end": "00:03:01,571", "text": "But I'm not good at keeping secrets.", "textRu": "Но я не умею хранить секреты."}, {"id": 77, "start": "00:03:01,649", "end": "00:03:03,650", "text": "It's not hard. Just keep your mouth shut.", "textRu": "Это не сложно. Просто держи рот на замке."}, {"id": 78, "start": "00:03:03,728", "end": "00:03:05,551", "text": "But I'm not good at keeping my mouth shut.", "textRu": "Но я не умею держать язык за зубами."}, {"id": 79, "start": "00:03:05,629", "end": "00:03:09,338", "text": "Sheldon, all you got to do... is be cool.", "textRu": "Шелдон, все, что тебе нужно делать... это быть крутым."}, {"id": 80, "start": "00:03:11,900", "end": "00:03:13,189", "text": "\"Be cool.\"", "textRu": "«Будь крутым»."}, {"id": 81, "start": "00:03:13,329", "end": "00:03:16,229", "text": "He might as well have asked me to fly around the backyard.", "textRu": "С тем же успехом он мог бы попросить меня полетать по заднему двору."}, {"id": 82, "start": "00:03:18,347", "end": "00:03:20,414", "text": "- Good night, baby. - Night, Mama.", "textRu": "- Спокойной ночи, детка. - Спокойной ночи, мама."}, {"id": 83, "start": "00:03:20,492", "end": "00:03:22,588", "text": "- Love you. - Love you, too.", "textRu": "- Люблю тебя. - Тоже тебя люблю."}, {"id": 84, "start": "00:03:24,556", "end": "00:03:26,306", "text": "Oh, hello.", "textRu": "О, привет."}, {"id": 85, "start": "00:03:26,418", "end": "00:03:29,619", "text": "I was just brushing  my teeth like I do every night.", "textRu": "Я просто чистил зубы, как делаю каждый вечер."}, {"id": 86, "start": "00:03:29,899", "end": "00:03:32,127", "text": "Ah, ha! Nothing new there.", "textRu": "Ах, ха! Ничего нового там нет."}, {"id": 87, "start": "00:03:32,273", "end": "00:03:33,426", "text": "You all right?", "textRu": "С тобой все в порядке?"}, {"id": 88, "start": "00:03:33,504", "end": "00:03:35,478", "text": "Yes. I'm cool.", "textRu": "Да. Я крут."}, {"id": 89, "start": "00:03:35,556", "end": "00:03:37,038", "text": "I'm very cool.", "textRu": "Я очень крут."}, {"id": 90, "start": "00:03:37,126", "end": "00:03:38,689", "text": "Tell Sheldon what cool means.", "textRu": "Расскажи Шелдону, что значит круто."}, {"id": 91, "start": "00:03:38,767", "end": "00:03:39,892", "text": "Hush.", "textRu": "Тише."}, {"id": 92, "start": "00:03:40,603", "end": "00:03:42,066", "text": "Sweet dreams.", "textRu": "Сладкие сны."}, {"id": 93, "start": "00:03:42,144", "end": "00:03:43,282", "text": "Love you.", "textRu": "Люблю тебя."}, {"id": 94, "start": "00:03:43,955", "end": "00:03:46,901", "text": "Love you, too, 'cause you're my mom.", "textRu": "Я тоже тебя люблю, потому что ты моя мама."}, {"id": 95, "start": "00:03:54,870", "end": "00:03:56,423", "text": "You're so weird.", "textRu": "Ты такой странный."}, {"id": 96, "start": "00:03:56,884", "end": "00:03:58,447", "text": "More than usual?", "textRu": "Больше, чем обычно?"}, {"id": 97, "start": "00:03:59,368", "end": "00:04:01,204", "text": "No, I guess not.", "textRu": "Нет, я думаю, нет."}, {"id": 98, "start": "00:04:01,640", "end": "00:04:03,064", "text": "Perfect.", "textRu": "Идеальный."}, {"id": 99, "start": "00:04:03,960", "end": "00:04:06,040", "text": "To avoid looking suspicious,", "textRu": "Чтобы не выглядеть подозрительно,"}, {"id": 100, "start": "00:04:06,118", "end": "00:04:09,367", "text": "I tried to interact with my mom as little as possible.", "textRu": "Я старалась как можно меньше общаться с мамой."}, {"id": 101, "start": "00:04:09,445", "end": "00:04:12,565", "text": "Thankfully, it's rude to speak with your mouth full.", "textRu": "К счастью, говорить с набитым ртом — невежливо."}, {"id": 102, "start": "00:04:12,691", "end": "00:04:15,035", "text": "You look tired, baby. Sleep okay?", "textRu": "Ты выглядишь уставшей, детка. Спи, ладно?"}, {"id": 103, "start": "00:04:15,228", "end": "00:04:16,399", "text": "Mm-hmm.", "textRu": "Мм-хм."}, {"id": 104, "start": "00:04:18,853", "end": "00:04:21,862", "text": "So how big a tax refund you think we're gonna get?", "textRu": "Как думаешь, какой размер налогового возмещения мы получим?"}, {"id": 105, "start": "00:04:22,587", "end": "00:04:23,664", "text": "Mm.", "textRu": "Мм."}, {"id": 106, "start": "00:04:24,345", "end": "00:04:25,877", "text": "- Mornin'. - Mornin'.", "textRu": "- Утро. - Утро."}, {"id": 107, "start": "00:04:25,955", "end": "00:04:27,793", "text": "I slept in the nude last night.", "textRu": "Прошлой ночью я спал обнаженным."}, {"id": 108, "start": "00:04:27,871", "end": "00:04:30,096", "text": "Felt every little breeze.", "textRu": "Чувствовал каждый легкий ветерок."}, {"id": 109, "start": "00:04:30,603", "end": "00:04:32,393", "text": "Thank you for sharing that.", "textRu": "Спасибо, что поделились этим."}, {"id": 110, "start": "00:04:32,736", "end": "00:04:34,049", "text": "You're welcome.", "textRu": "Пожалуйста."}, {"id": 111, "start": "00:04:34,286", "end": "00:04:36,994", "text": "Fight, you cowards, fight!", "textRu": "Сражайтесь, трусы, сражайтесь!"}, {"id": 112, "start": "00:04:37,072", "end": "00:04:39,393", "text": "You fight, Skeletor.", "textRu": "Ты сражаешься, Скелетор."}, {"id": 113, "start": "00:04:40,447", "end": "00:04:43,111", "text": "Mare, we got any batteries?!", "textRu": "Маре, у нас есть батарейки?!"}, {"id": 114, "start": "00:04:43,189", "end": "00:04:46,471", "text": "Look in the drawer by the refrigerator.", "textRu": "Загляните в ящик возле холодильника."}, {"id": 115, "start": "00:04:46,900", "end": "00:04:49,416", "text": "There was only so much food I could eat,", "textRu": "Я мог съесть столько еды,"}, {"id": 116, "start": "00:04:49,494", "end": "00:04:53,205", "text": "so I started avoiding my mother whenever possible.", "textRu": "поэтому я начал избегать своей матери, когда это было возможно."}, {"id": 117, "start": "00:04:55,759", "end": "00:04:57,333", "text": "What are you doing in there?", "textRu": "Что ты там делаешь?"}, {"id": 118, "start": "00:04:57,411", "end": "00:04:59,065", "text": "Keeping your secret.", "textRu": "Сохраняя свою тайну."}, {"id": 119, "start": "00:04:59,150", "end": "00:05:00,572", "text": "You got to pull it together.", "textRu": "Вы должны собрать это воедино."}, {"id": 120, "start": "00:05:00,650", "end": "00:05:02,599", "text": "This is me pulling it together.", "textRu": "Это я собираю это воедино."}, {"id": 121, "start": "00:05:02,677", "end": "00:05:04,416", "text": "- Pull harder. - Find 'em?", "textRu": "- Тяни сильнее. - Найти их?"}, {"id": 122, "start": "00:05:04,591", "end": "00:05:07,096", "text": "Yeah. Got 'em. Thanks.", "textRu": "Ага. Получил их. Спасибо."}, {"id": 123, "start": "00:05:07,174", "end": "00:05:09,781", "text": "You're very welcome. Hey, have you noticed", "textRu": "Всегда пожалуйста. Эй, ты заметил?"}, {"id": 124, "start": "00:05:09,859", "end": "00:05:11,409", "text": "anything off with Sheldon?", "textRu": "что-то не так с Шелдоном?"}, {"id": 125, "start": "00:05:11,487", "end": "00:05:14,547", "text": "Uh, no, no, no. Can't say that I have. Why?", "textRu": "Э-э, нет, нет, нет. Не могу сказать, что у меня есть. Почему?"}, {"id": 126, "start": "00:05:14,625", "end": "00:05:16,008", "text": "He's been awful quiet,", "textRu": "Он был ужасно тихим,"}, {"id": 127, "start": "00:05:16,086", "end": "00:05:17,784", "text": "and, at the risk of being indelicate,", "textRu": "и, рискуя показаться нескромным,"}, {"id": 128, "start": "00:05:17,862", "end": "00:05:19,750", "text": "he's gone several days", "textRu": "его нет несколько дней"}, {"id": 129, "start": "00:05:19,828", "end": "00:05:21,437", "text": "without a bowel movement.", "textRu": "без дефекации."}, {"id": 130, "start": "00:05:21,539", "end": "00:05:22,688", "text": "How do you know that?", "textRu": "Откуда ты это знаешь?"}, {"id": 131, "start": "00:05:22,766", "end": "00:05:24,203", "text": "Well, I was worried about him,", "textRu": "Ну, я волновалась за него,"}, {"id": 132, "start": "00:05:24,281", "end": "00:05:25,992", "text": "so I took a look in his potty journal.", "textRu": "поэтому я заглянул в его дневник горшка."}, {"id": 133, "start": "00:05:26,070", "end": "00:05:27,563", "text": "He's still keeping that thing, huh?", "textRu": "Он все еще хранит эту штуку, да?"}, {"id": 134, "start": "00:05:27,641", "end": "00:05:30,423", "text": "Oh, yeah, that's why he wanted the Polaroid camera.", "textRu": "О да, именно поэтому ему нужна была камера Polaroid."}, {"id": 135, "start": "00:05:31,564", "end": "00:05:33,844", "text": "Uh, well, I'm sure he's gonna be fine,", "textRu": "Ну, я уверен, что с ним все будет в порядке,"}, {"id": 136, "start": "00:05:33,922", "end": "00:05:35,895", "text": "uh, but I'll keep an eye on him.", "textRu": "эээ, но я присмотрю за ним."}, {"id": 137, "start": "00:05:35,973", "end": "00:05:37,641", "text": "- Thank you. - You got it.", "textRu": "- Спасибо. - Вы поняли."}, {"id": 138, "start": "00:05:41,520", "end": "00:05:44,445", "text": "- She's gone. - Thank you.", "textRu": "- Она ушла. - Спасибо."}, {"id": 139, "start": "00:05:44,523", "end": "00:05:46,900", "text": "Batteries are in this drawer.", "textRu": "Батарейки находятся в этом ящике."}, {"id": 140, "start": "00:05:55,006", "end": "00:05:56,526", "text": "We got a problem.", "textRu": "У нас возникла проблема."}, {"id": 141, "start": "00:05:59,884", "end": "00:06:01,830", "text": "I don't know how much longer Sheldon can hold out.", "textRu": "Я не знаю, как долго Шелдон сможет продержаться."}, {"id": 142, "start": "00:06:01,908", "end": "00:06:04,164", "text": "This is why I did not want you to write a check.", "textRu": "Вот почему я не хотел, чтобы вы выписывали чек."}, {"id": 143, "start": "00:06:04,242", "end": "00:06:05,782", "text": "Well, I'm sorry, but I didn't have", "textRu": "Ну, извини, но у меня не было"}, {"id": 144, "start": "00:06:05,860", "end": "00:06:07,207", "text": "that kind of cash lying around.", "textRu": "такие деньги валяются повсюду."}, {"id": 145, "start": "00:06:07,285", "end": "00:06:09,425", "text": "I do not want Mary to find out about this.", "textRu": "Я не хочу, чтобы Мэри узнала об этом."}, {"id": 146, "start": "00:06:09,503", "end": "00:06:10,925", "text": "Well, what about Sheldon?", "textRu": "Ну, а что насчет Шелдона?"}, {"id": 147, "start": "00:06:11,003", "end": "00:06:13,474", "text": "The kid hasn't pooped in days, he might pop.", "textRu": "Ребенок уже несколько дней не какал, может и лопнет."}, {"id": 148, "start": "00:06:13,552", "end": "00:06:16,539", "text": "Slip a little Metamucil into his apple juice, he'll be fine.", "textRu": "Добавьте немного Метамуцила ему в яблочный сок, и с ним все будет в порядке."}, {"id": 149, "start": "00:06:16,617", "end": "00:06:18,471", "text": "Why don't we just come clean?", "textRu": "Почему бы нам просто не признаться?"}, {"id": 150, "start": "00:06:20,892", "end": "00:06:22,916", "text": "All right, sure, we could do that.", "textRu": "Хорошо, конечно, мы могли бы это сделать."}, {"id": 151, "start": "00:06:23,365", "end": "00:06:25,932", "text": "You could rat me out to Mary and...", "textRu": "Ты мог бы сдать меня Мэри и..."}, {"id": 152, "start": "00:06:26,509", "end": "00:06:29,424", "text": "I could tell her what you did at the church picnic.", "textRu": "Я мог бы рассказать ей, что ты делал на церковном пикнике."}, {"id": 153, "start": "00:06:29,727", "end": "00:06:31,017", "text": "Come on.", "textRu": "Ну давай же."}, {"id": 154, "start": "00:06:31,345", "end": "00:06:32,761", "text": "Now you're just playing dirty.", "textRu": "Теперь ты просто играешь грязно."}, {"id": 155, "start": "00:06:32,839", "end": "00:06:35,325", "text": "We sink or swim together, George.", "textRu": "Мы тонем или плывем вместе, Джордж."}, {"id": 156, "start": "00:06:35,415", "end": "00:06:37,744", "text": "We sink or swim together.", "textRu": "Мы тонем или плывем вместе."}, {"id": 157, "start": "00:06:44,118", "end": "00:06:46,104", "text": "Grandmas are supposed to be nice.", "textRu": "Бабушки должны быть хорошими."}, {"id": 158, "start": "00:06:46,182", "end": "00:06:48,229", "text": "What went wrong with you?", "textRu": "Что с тобой пошло не так?"}, {"id": 159, "start": "00:06:51,142", "end": "00:06:53,274", "text": "Avoiding my mother in our own house", "textRu": "Избегаем маму в собственном доме"}, {"id": 160, "start": "00:06:53,352", "end": "00:06:54,908", "text": "was proving to be difficult,", "textRu": "оказалось трудным,"}, {"id": 161, "start": "00:06:54,986", "end": "00:06:57,299", "text": "so it was time to get creative.", "textRu": "так что пришло время проявить творческий подход."}, {"id": 162, "start": "00:06:57,509", "end": "00:07:00,638", "text": "Hello. I'd like to book a room in your hotel.", "textRu": "Привет. Я хотел бы забронировать номер в вашем отеле."}, {"id": 163, "start": "00:07:01,508", "end": "00:07:03,556", "text": "I'd be arriving tonight.", "textRu": "Я приеду сегодня вечером."}, {"id": 164, "start": "00:07:04,134", "end": "00:07:06,236", "text": "No, it's just me.", "textRu": "Нет, это только я."}, {"id": 165, "start": "00:07:07,306", "end": "00:07:10,087", "text": "Ooh, a queen bed, that sounds fancy.", "textRu": "Ох, двуспальная кровать, это звучит заманчиво."}, {"id": 166, "start": "00:07:10,165", "end": "00:07:12,838", "text": "And how much would this room cost?", "textRu": "И сколько будет стоить эта комната?"}, {"id": 167, "start": "00:07:14,321", "end": "00:07:16,510", "text": "Wow. Is that per month?", "textRu": "Ух ты. Это в месяц?"}, {"id": 168, "start": "00:07:17,634", "end": "00:07:19,376", "text": "Per day?", "textRu": "В день?"}, {"id": 169, "start": "00:07:20,563", "end": "00:07:23,236", "text": "By any chance, do you have a children's rate?", "textRu": "У вас случайно нет детского тарифа?"}, {"id": 170, "start": "00:07:24,509", "end": "00:07:27,463", "text": "We've been friends for a while now, haven't we?", "textRu": "Мы уже давно друзья, не так ли?"}, {"id": 171, "start": "00:07:27,938", "end": "00:07:29,354", "text": "I suppose so.", "textRu": "Я полагаю, да."}, {"id": 172, "start": "00:07:29,517", "end": "00:07:31,873", "text": "Given that, how would you feel about a sleepover?", "textRu": "Учитывая это, как бы вы отнеслись к ночевке?"}, {"id": 173, "start": "00:07:31,951", "end": "00:07:34,104", "text": "Sure. Your mom lets you watch TV.", "textRu": "Конечно. Твоя мама разрешает тебе смотреть телевизор."}, {"id": 174, "start": "00:07:34,204", "end": "00:07:36,127", "text": "Jake and the Fatman is on tonight.", "textRu": "Джейк и Толстяк сегодня вечером."}, {"id": 175, "start": "00:07:36,313", "end": "00:07:38,353", "text": "I meant we could sleep at your house.", "textRu": "Я имел в виду, что мы могли бы переночевать у тебя дома."}, {"id": 176, "start": "00:07:38,431", "end": "00:07:40,338", "text": "But you'll miss Jake and the Fatman.", "textRu": "Но ты будешь скучать по Джейку и Толстяку."}, {"id": 177, "start": "00:07:40,485", "end": "00:07:42,643", "text": "Even better. So what do you say?", "textRu": "Даже лучше. Так что ты скажешь?"}, {"id": 178, "start": "00:07:43,688", "end": "00:07:44,973", "text": "I'll have to ask my mom.", "textRu": "Мне придется спросить у мамы."}, {"id": 179, "start": "00:07:45,071", "end": "00:07:47,774", "text": "Well, be sure to tell her I'm clean, I'm well-behaved,", "textRu": "Ну, обязательно скажи ей, что я чист, веду себя хорошо,"}, {"id": 180, "start": "00:07:47,852", "end": "00:07:49,222", "text": "and if you don't have a lot of room,", "textRu": "а если у тебя мало места,"}, {"id": 181, "start": "00:07:49,300", "end": "00:07:51,402", "text": "I can fit in really tight spaces.", "textRu": "Я могу поместиться в очень ограниченном пространстве."}, {"id": 182, "start": "00:07:55,942", "end": "00:07:57,608", "text": "So your first sleepover.", "textRu": "Итак, ваша первая ночевка."}, {"id": 183, "start": "00:07:57,686", "end": "00:07:59,152", "text": "Pretty exciting, huh?", "textRu": "Довольно захватывающе, да?"}, {"id": 184, "start": "00:07:59,230", "end": "00:08:02,181", "text": "No. It's not exciting, it's constipating,", "textRu": "Нет. Это не возбуждает, это вызывает запор."}, {"id": 185, "start": "00:08:02,259", "end": "00:08:04,471", "text": "and I'm only doing it to avoid Mom.", "textRu": "и я делаю это только для того, чтобы избежать встречи с мамой."}, {"id": 186, "start": "00:08:04,845", "end": "00:08:07,067", "text": "But still, it's your first sleepover.", "textRu": "Но все равно это твоя первая ночевка."}, {"id": 187, "start": "00:08:07,145", "end": "00:08:08,689", "text": "It's fun stuff.", "textRu": "Это забавная штука."}, {"id": 188, "start": "00:08:10,173", "end": "00:08:12,222", "text": "Okay, I know you're having a tough time with this,", "textRu": "Хорошо, я знаю, что у тебя с этим тяжелые времена,"}, {"id": 189, "start": "00:08:12,300", "end": "00:08:14,728", "text": "but... you're doing great.", "textRu": "но... у тебя все отлично."}, {"id": 190, "start": "00:08:15,603", "end": "00:08:17,316", "text": "You spend some time at Tam's house,", "textRu": "Ты проводишь некоторое время в доме Тэма,"}, {"id": 191, "start": "00:08:17,394", "end": "00:08:20,326", "text": "you know, clear your head, and come back home refreshed.", "textRu": "знаешь, очисти голову и возвращайся домой отдохнувшим."}, {"id": 192, "start": "00:08:20,404", "end": "00:08:21,753", "text": "And then I can tell Mom?", "textRu": "И тогда я смогу сказать маме?"}, {"id": 193, "start": "00:08:21,831", "end": "00:08:23,736", "text": "Oh, no, you can never tell Mom.", "textRu": "О, нет, ты никогда не расскажешь маме."}, {"id": 194, "start": "00:08:24,087", "end": "00:08:26,588", "text": "Wouldn't it be easier to just be honest?", "textRu": "Не проще ли быть честным?"}, {"id": 195, "start": "00:08:26,767", "end": "00:08:29,010", "text": "Usually, it would be, but...", "textRu": "Обычно так и было бы, но..."}, {"id": 196, "start": "00:08:29,157", "end": "00:08:31,393", "text": "sometimes the truth can hurt people.", "textRu": "иногда правда может ранить людей."}, {"id": 197, "start": "00:08:32,696", "end": "00:08:34,410", "text": "We wouldn't want to hurt Mom, right?", "textRu": "Мы бы не хотели причинить вред маме, верно?"}, {"id": 198, "start": "00:08:34,488", "end": "00:08:35,768", "text": "Of course not.", "textRu": "Конечно, нет."}, {"id": 199, "start": "00:08:35,851", "end": "00:08:37,119", "text": "Attaboy.", "textRu": "Молодец."}, {"id": 200, "start": "00:08:40,823", "end": "00:08:43,748", "text": "Hey, here's a funny prank you can try tonight.", "textRu": "Эй, вот забавный розыгрыш, который ты можешь попробовать сегодня вечером."}, {"id": 201, "start": "00:08:43,826", "end": "00:08:46,597", "text": "When Tam falls asleep, put some shaving cream in his hand", "textRu": "Когда Тэм заснет, возьми ему в руку немного крема для бритья."}, {"id": 202, "start": "00:08:46,675", "end": "00:08:48,051", "text": "and then tickle his nose.", "textRu": "а затем пощекотать ему нос."}, {"id": 203, "start": "00:08:48,129", "end": "00:08:49,173", "text": "Why?", "textRu": "Почему?"}, {"id": 204, "start": "00:08:49,368", "end": "00:08:51,142", "text": "'Cause then he'll go to,", "textRu": "Потому что тогда он пойдет,"}, {"id": 205, "start": "00:08:51,220", "end": "00:08:52,441", "text": "you know, scratch his nose,", "textRu": "знаешь, почеши ему нос,"}, {"id": 206, "start": "00:08:52,519", "end": "00:08:54,485", "text": "and he gets shaving cream on his face.", "textRu": "и ему на лицо попадает крем для бритья."}, {"id": 207, "start": "00:08:54,743", "end": "00:08:56,020", "text": "And then what?", "textRu": "И что потом?"}, {"id": 208, "start": "00:08:56,126", "end": "00:08:59,111", "text": "Well... that-that's it.", "textRu": "Ну... вот и всё."}, {"id": 209, "start": "00:08:59,595", "end": "00:09:01,196", "text": "But I'm a guest in their home,", "textRu": "Но я гость в их доме,"}, {"id": 210, "start": "00:09:01,274", "end": "00:09:03,090", "text": "and that doesn't seem like a very good way", "textRu": "и это не кажется очень хорошим способом"}, {"id": 211, "start": "00:09:03,168", "end": "00:09:04,650", "text": "to repay their kindness.", "textRu": "чтобы отплатить за их доброту."}, {"id": 212, "start": "00:09:04,829", "end": "00:09:06,213", "text": "Never mind.", "textRu": "Неважно."}, {"id": 213, "start": "00:09:06,462", "end": "00:09:08,464", "text": "And what if the shaving cream gets in his eyes?", "textRu": "А что, если крем для бритья попадет ему в глаза?"}, {"id": 214, "start": "00:09:08,542", "end": "00:09:09,563", "text": "That would sting.", "textRu": "Это будет больно."}, {"id": 215, "start": "00:09:09,641", "end": "00:09:10,844", "text": "Sorry I mentioned it.", "textRu": "Извините, что упомянул об этом."}, {"id": 216, "start": "00:09:10,922", "end": "00:09:12,683", "text": "Also, I didn't bring my own shaving cream.", "textRu": "Кроме того, я не взял с собой свой крем для бритья."}, {"id": 217, "start": "00:09:12,761", "end": "00:09:14,947", "text": "I'd have to use his dad's, and that... Forget it!", "textRu": "Мне придется воспользоваться услугами его отца, и это... Забудь об этом!"}, {"id": 218, "start": "00:09:21,815", "end": "00:09:22,817", "text": "Hello.", "textRu": "Привет."}, {"id": 219, "start": "00:09:22,895", "end": "00:09:25,114", "text": "Hi. You must be Mrs....", "textRu": "Привет. Вы, должно быть, миссис...."}, {"id": 220, "start": "00:09:25,192", "end": "00:09:26,254", "text": "Tam's mom.", "textRu": "Мама Тэма."}, {"id": 221, "start": "00:09:26,332", "end": "00:09:28,349", "text": "I'm Sheldon's dad, George Cooper.", "textRu": "Я отец Шелдона, Джордж Купер."}, {"id": 222, "start": "00:09:28,427", "end": "00:09:29,441", "text": "Nice to meet you.", "textRu": "Рад встрече."}, {"id": 223, "start": "00:09:29,519", "end": "00:09:31,114", "text": "Thanks for letting him spend the night.", "textRu": "Спасибо, что позволил ему переночевать."}, {"id": 224, "start": "00:09:31,245", "end": "00:09:32,996", "text": "It's his first sleepover. He's excited.", "textRu": "Это его первая ночевка. Он взволнован."}, {"id": 225, "start": "00:09:33,074", "end": "00:09:34,796", "text": "Actually, I'm quite apprehens...", "textRu": "На самом деле, я очень опасаюсь..."}, {"id": 226, "start": "00:09:34,874", "end": "00:09:36,566", "text": "He's really looking forward to it.", "textRu": "Он очень этого ждет."}, {"id": 227, "start": "00:09:36,644", "end": "00:09:37,972", "text": "Uh, in case something", "textRu": "Э-э, на случай чего"}, {"id": 228, "start": "00:09:38,050", "end": "00:09:39,794", "text": "comes up, just give us a holler.", "textRu": "придет, просто позвони нам."}, {"id": 229, "start": "00:09:39,872", "end": "00:09:40,962", "text": "I mean, a call.", "textRu": "Я имею в виду звонок."}, {"id": 230, "start": "00:09:41,040", "end": "00:09:43,127", "text": "If you hollered, we wouldn't hear you.", "textRu": "Если бы вы кричали, мы бы вас не услышали."}, {"id": 231, "start": "00:09:44,009", "end": "00:09:46,098", "text": "That-that was a joke.", "textRu": "Это-это была шутка."}, {"id": 232, "start": "00:09:46,402", "end": "00:09:47,809", "text": "Ha-ha-ha!", "textRu": "Ха-ха-ха!"}, {"id": 233, "start": "00:09:48,105", "end": "00:09:50,043", "text": "Okay, buddy, have fun.", "textRu": "Ладно, приятель, веселись."}, {"id": 234, "start": "00:09:52,456", "end": "00:09:54,011", "text": "Visiting Tam's house", "textRu": "Посещение дома Тэма"}, {"id": 235, "start": "00:09:54,089", "end": "00:09:56,959", "text": "for the first time was an emotional roller coaster.", "textRu": "впервые это были эмоциональные американские горки."}, {"id": 236, "start": "00:09:57,037", "end": "00:09:59,988", "text": "For example, it's traditional in Vietnamese homes", "textRu": "Например, во вьетнамских домах это традиционно."}, {"id": 237, "start": "00:10:00,066", "end": "00:10:03,084", "text": "to have gruesome religious iconography near the entrance.", "textRu": "возле входа располагать ужасную религиозную иконографию."}, {"id": 238, "start": "00:10:03,162", "end": "00:10:05,058", "text": "I did not like that.", "textRu": "Мне это не понравилось."}, {"id": 239, "start": "00:10:05,136", "end": "00:10:07,159", "text": "However, it's also customary", "textRu": "Однако это тоже принято"}, {"id": 240, "start": "00:10:07,237", "end": "00:10:08,959", "text": "to not wear shoes around the house", "textRu": "не носить обувь дома"}, {"id": 241, "start": "00:10:09,037", "end": "00:10:10,684", "text": "for sanitary reasons.", "textRu": "по санитарным соображениям."}, {"id": 242, "start": "00:10:11,120", "end": "00:10:12,600", "text": "I did like that.", "textRu": "Мне это понравилось."}, {"id": 243, "start": "00:10:12,678", "end": "00:10:13,893", "text": "Interestingly,", "textRu": "Интересно,"}, {"id": 244, "start": "00:10:13,971", "end": "00:10:16,928", "text": "one of the main ingredients in Vietnamese cooking", "textRu": "один из основных ингредиентов вьетнамской кухни"}, {"id": 245, "start": "00:10:17,006", "end": "00:10:20,576", "text": "is an extremely pungent condiment known as fish sauce.", "textRu": "— чрезвычайно острая приправа, известная как рыбный соус."}, {"id": 246, "start": "00:10:20,654", "end": "00:10:22,309", "text": "I did not like that.", "textRu": "Мне это не понравилось."}, {"id": 247, "start": "00:10:22,456", "end": "00:10:24,347", "text": "But before every meal,", "textRu": "Но перед каждым приемом пищи"}, {"id": 248, "start": "00:10:24,425", "end": "00:10:27,856", "text": "it's common for everyone to wash their hands and face.", "textRu": "всем свойственно мыть руки и лицо."}, {"id": 249, "start": "00:10:27,934", "end": "00:10:29,484", "text": "I did like that.", "textRu": "Мне это понравилось."}, {"id": 250, "start": "00:10:29,562", "end": "00:10:33,284", "text": "Forks are not customary in a Vietnamese household.", "textRu": "Вилки не приняты во вьетнамском доме."}, {"id": 251, "start": "00:10:35,298", "end": "00:10:37,214", "text": "I did not like that.", "textRu": "Мне это не понравилось."}, {"id": 252, "start": "00:10:37,292", "end": "00:10:40,495", "text": "And instead of napkins, there was one towel", "textRu": "И вместо салфеток было одно полотенце"}, {"id": 253, "start": "00:10:40,573", "end": "00:10:42,489", "text": "for everyone to share at the table.", "textRu": "чтобы все могли разделить за столом."}, {"id": 254, "start": "00:10:43,609", "end": "00:10:45,770", "text": "Seriously, what are they thinking?", "textRu": "Серьезно, о чем они думают?"}, {"id": 255, "start": "00:10:47,527", "end": "00:10:49,381", "text": "I can't help thinking how odd it is", "textRu": "Я не могу отделаться от мысли, как это странно"}, {"id": 256, "start": "00:10:49,459", "end": "00:10:51,873", "text": "that Shelly volunteered to go on a sleepover.", "textRu": "что Шелли вызвалась пойти на ночевку."}, {"id": 257, "start": "00:10:51,951", "end": "00:10:53,076", "text": "Oh, I don't know.", "textRu": "О, я не знаю."}, {"id": 258, "start": "00:10:53,154", "end": "00:10:54,876", "text": "Hmm? He's growing up.", "textRu": "Хм? Он растет."}, {"id": 259, "start": "00:10:54,954", "end": "00:10:57,620", "text": "It's natural for a young boy to want to spread his wings", "textRu": "Для маленького мальчика вполне естественно желание расправить крылья."}, {"id": 260, "start": "00:10:57,698", "end": "00:10:59,249", "text": "a little bit, try something new.", "textRu": "немного, попробовать что-то новое."}, {"id": 261, "start": "00:10:59,327", "end": "00:11:00,691", "text": "That's nonsense.", "textRu": "Это ерунда."}, {"id": 262, "start": "00:11:00,769", "end": "00:11:01,883", "text": "Last week, I brought home", "textRu": "На прошлой неделе я принес домой"}, {"id": 263, "start": "00:11:01,961", "end": "00:11:03,912", "text": "the Raisin Bran with the sugar on the raisins.", "textRu": "Изюмные отруби с сахаром на изюме."}, {"id": 264, "start": "00:11:03,990", "end": "00:11:05,629", "text": "He almost lost his mind.", "textRu": "Он почти потерял рассудок."}, {"id": 265, "start": "00:11:06,308", "end": "00:11:07,605", "text": "If you ask me,", "textRu": "Если вы спросите меня,"}, {"id": 266, "start": "00:11:07,683", "end": "00:11:09,449", "text": "you're worried about nothing.", "textRu": "ты беспокоишься ни о чем."}, {"id": 267, "start": "00:11:10,339", "end": "00:11:11,370", "text": "Maybe it's me.", "textRu": "Может быть, это я."}, {"id": 268, "start": "00:11:11,448", "end": "00:11:13,723", "text": "Maybe I did something to upset him.", "textRu": "Возможно, я сделал что-то, что его расстроило."}, {"id": 269, "start": "00:11:13,964", "end": "00:11:15,677", "text": "What are you talking about?", "textRu": "О чем ты говоришь?"}, {"id": 270, "start": "00:11:15,755", "end": "00:11:17,788", "text": "He loves you like crazy.", "textRu": "Он любит тебя как сумасшедший."}, {"id": 271, "start": "00:11:17,889", "end": "00:11:19,769", "text": "Much more than he loves this one.", "textRu": "Гораздо больше, чем он любит этот."}, {"id": 272, "start": "00:11:19,847", "end": "00:11:20,835", "text": "It's true.", "textRu": "Это правда."}, {"id": 273, "start": "00:11:20,913", "end": "00:11:22,036", "text": "I don't know.", "textRu": "Я не знаю."}, {"id": 274, "start": "00:11:22,114", "end": "00:11:24,560", "text": "I just feel like something isn't right.", "textRu": "Я просто чувствую, что что-то не так."}, {"id": 275, "start": "00:11:25,198", "end": "00:11:26,256", "text": "Mom!", "textRu": "Мама!"}, {"id": 276, "start": "00:11:26,409", "end": "00:11:28,324", "text": "I got my hair stuck in my zipper!", "textRu": "У меня волосы застряли в молнии!"}, {"id": 277, "start": "00:11:28,402", "end": "00:11:30,864", "text": "That's the kid you need to be worried about.", "textRu": "Это тот ребенок, о котором вам стоит беспокоиться."}, {"id": 278, "start": "00:11:34,034", "end": "00:11:35,919", "text": "Okay, Connie, why don't we just come clean?", "textRu": "Ладно, Конни, почему бы нам просто не признаться?"}, {"id": 279, "start": "00:11:35,997", "end": "00:11:38,028", "text": "- No. - You heard her.", "textRu": "- Нет. - Ты ее слышал."}, {"id": 280, "start": "00:11:38,198", "end": "00:11:40,051", "text": "Now she's blaming herself.", "textRu": "Теперь она винит себя."}, {"id": 281, "start": "00:11:40,222", "end": "00:11:41,282", "text": "And Sheldon's so upset", "textRu": "И Шелдон так расстроен"}, {"id": 282, "start": "00:11:41,360", "end": "00:11:43,745", "text": "he's... he's acting like a regular kid.", "textRu": "он... он ведет себя как обычный ребенок."}, {"id": 283, "start": "00:11:43,823", "end": "00:11:45,659", "text": "- All right, let's tell her. - Thank you.", "textRu": "- Хорошо, давай ей скажем. - Спасибо."}, {"id": 284, "start": "00:11:45,737", "end": "00:11:48,060", "text": "But first I'm gonna tell her what you did at the picnic.", "textRu": "Но сначала я расскажу ей, что ты делал на пикнике."}, {"id": 285, "start": "00:11:48,138", "end": "00:11:50,418", "text": "- Oh, Mary! - Okay, okay, shh.", "textRu": "- О, Мэри! - Ладно, ладно, тсс."}, {"id": 286, "start": "00:11:54,620", "end": "00:11:56,745", "text": "I don't know how much longer we can keep this going.", "textRu": "Я не знаю, как долго мы сможем это продолжать."}, {"id": 287, "start": "00:11:56,823", "end": "00:11:58,680", "text": "I'm willing to find out.", "textRu": "Я хочу это выяснить."}, {"id": 288, "start": "00:12:06,050", "end": "00:12:08,909", "text": "So, this game is called Mystic Warlords of Ka'a.", "textRu": "Итак, эта игра называется Mystic Warlords of Ka'a."}, {"id": 289, "start": "00:12:08,987", "end": "00:12:10,057", "text": "It's pretty fun.", "textRu": "Это довольно весело."}, {"id": 290, "start": "00:12:10,135", "end": "00:12:12,174", "text": "There are six kinds of secret warlords...", "textRu": "Есть шесть видов тайных военачальников..."}, {"id": 291, "start": "00:12:12,252", "end": "00:12:15,481", "text": "- Secret warlords. - It's a secret. Secret.", "textRu": "- Тайные военачальники. - Это секрет. Секрет."}, {"id": 292, "start": "00:12:15,559", "end": "00:12:16,675", "text": "It's a secret.", "textRu": "Это секрет."}, {"id": 293, "start": "00:12:16,753", "end": "00:12:18,568", "text": "Have you noticed anything off with Sheldon?", "textRu": "Вы заметили что-нибудь неладное с Шелдоном?"}, {"id": 294, "start": "00:12:18,646", "end": "00:12:19,943", "text": "Something between me and you.", "textRu": "Что-то между мной и тобой."}, {"id": 295, "start": "00:12:20,021", "end": "00:12:21,636", "text": "Mom is on a need-to-know basis.", "textRu": "Мама в порядке служебной необходимости."}, {"id": 296, "start": "00:12:21,714", "end": "00:12:23,558", "text": "I took a little look in his potty journal.", "textRu": "Я заглянул в его дневник горшка."}, {"id": 297, "start": "00:12:23,636", "end": "00:12:26,021", "text": "- It's a secret. - Several days without a bowel movement.", "textRu": "- Это секрет. - Несколько дней без дефекации."}, {"id": 298, "start": "00:12:26,099", "end": "00:12:27,561", "text": "- Sheldon. - Secret. Secret.", "textRu": "- Шелдон. - Секрет. Секрет."}, {"id": 299, "start": "00:12:27,639", "end": "00:12:29,114", "text": "- A secret. - Sheldon.", "textRu": "- Секрет. - Шелдон."}, {"id": 300, "start": "00:12:29,448", "end": "00:12:31,403", "text": "Did you hear anything I said?", "textRu": "Ты слышал что-нибудь, что я сказал?"}, {"id": 301, "start": "00:12:31,761", "end": "00:12:35,387", "text": "Sorry, I was reliving a traumatic experience.", "textRu": "Извините, я заново пережил травмирующий опыт."}, {"id": 302, "start": "00:12:35,470", "end": "00:12:36,739", "text": "What do you mean?", "textRu": "Что ты имеешь в виду?"}, {"id": 303, "start": "00:12:39,370", "end": "00:12:42,050", "text": "Tam, I have a secret that's weighing on me,", "textRu": "Тэм, у меня есть секрет, который меня тяготит."}, {"id": 304, "start": "00:12:42,128", "end": "00:12:43,465", "text": "and I need to tell someone.", "textRu": "и мне нужно кому-нибудь рассказать."}, {"id": 305, "start": "00:12:43,572", "end": "00:12:44,839", "text": "Okay. Tell me.", "textRu": "Хорошо. Скажи мне."}, {"id": 306, "start": "00:12:45,198", "end": "00:12:46,884", "text": "But I promised I wouldn't.", "textRu": "Но я обещал, что не буду."}, {"id": 307, "start": "00:12:47,237", "end": "00:12:48,710", "text": "Okay. Then don't.", "textRu": "Хорошо. Тогда не надо."}, {"id": 308, "start": "00:12:48,886", "end": "00:12:50,706", "text": "But it's driving me crazy.", "textRu": "Но это сводит меня с ума."}, {"id": 309, "start": "00:12:50,784", "end": "00:12:52,123", "text": "Too bad you're not Catholic.", "textRu": "Жаль, что ты не католик."}, {"id": 310, "start": "00:12:52,201", "end": "00:12:53,746", "text": "You could confess it to a priest.", "textRu": "Вы могли бы исповедоваться в этом священнику."}, {"id": 311, "start": "00:12:54,519", "end": "00:12:55,949", "text": "That's a great idea.", "textRu": "Это отличная идея."}, {"id": 312, "start": "00:12:56,331", "end": "00:12:58,329", "text": "You're Catholic. I'll confess it to you.", "textRu": "Ты католик. Я признаюсь тебе в этом."}, {"id": 313, "start": "00:12:58,430", "end": "00:12:59,574", "text": "I'm not a priest.", "textRu": "Я не священник."}, {"id": 314, "start": "00:12:59,652", "end": "00:13:00,771", "text": "I'm not a Catholic.", "textRu": "Я не католик."}, {"id": 315, "start": "00:13:00,849", "end": "00:13:02,660", "text": "It makes perfect sense.", "textRu": "Это имеет смысл."}, {"id": 316, "start": "00:13:02,972", "end": "00:13:05,436", "text": "Okay, whenever you're ready.", "textRu": "Хорошо, когда будешь готов."}, {"id": 317, "start": "00:13:06,550", "end": "00:13:07,829", "text": "What are you doing?", "textRu": "Что ты делаешь?"}, {"id": 318, "start": "00:13:07,907", "end": "00:13:09,770", "text": "I'm assuming the position.", "textRu": "Я принимаю позицию."}, {"id": 319, "start": "00:13:10,098", "end": "00:13:11,546", "text": "Okay.", "textRu": "Хорошо."}, {"id": 320, "start": "00:13:12,136", "end": "00:13:14,423", "text": "Forgive me, Tam, for I have sinned.", "textRu": "Прости меня, Тэм, я согрешил."}, {"id": 321, "start": "00:13:14,511", "end": "00:13:16,447", "text": "This is my first confession.", "textRu": "Это моя первая исповедь."}, {"id": 322, "start": "00:13:16,527", "end": "00:13:18,504", "text": "I forgive you, my son.", "textRu": "Я прощаю тебя, сын мой."}, {"id": 323, "start": "00:13:19,519", "end": "00:13:23,317", "text": "I was doing my parents' taxes and noticed a check was missing.", "textRu": "Я платил налоги своих родителей и заметил, что чек пропал."}, {"id": 324, "start": "00:13:23,620", "end": "00:13:25,060", "text": "- I asked my father about it... - As I walked Tam", "textRu": "- Я спросил об этом отца... - Пока я шел, Тэм"}, {"id": 325, "start": "00:13:25,138", "end": "00:13:26,729", "text": "through the whole sordid affair,", "textRu": "через все это грязное дело,"}, {"id": 326, "start": "00:13:26,807", "end": "00:13:29,584", "text": "I could feel a weight lifting off my shoulders.", "textRu": "Я почувствовал, как тяжесть спала с моих плеч."}, {"id": 327, "start": "00:13:29,662", "end": "00:13:32,357", "text": "It was a relief to finally unburden myself", "textRu": "Для меня было облегчением наконец освободиться от бремени"}, {"id": 328, "start": "00:13:32,435", "end": "00:13:33,745", "text": "of this deception.", "textRu": "этого обмана."}, {"id": 329, "start": "00:13:33,823", "end": "00:13:35,405", "text": "By the time I reached the end,", "textRu": "К тому времени, как я дошел до конца,"}, {"id": 330, "start": "00:13:35,483", "end": "00:13:37,512", "text": "I felt like a new person.", "textRu": "Я почувствовал себя новым человеком."}, {"id": 331, "start": "00:13:37,823", "end": "00:13:39,473", "text": "That's the whole story.", "textRu": "Вот и вся история."}, {"id": 332, "start": "00:13:40,495", "end": "00:13:41,947", "text": "Cool. Can we play now?", "textRu": "Прохладный. Можем ли мы играть сейчас?"}, {"id": 333, "start": "00:13:42,025", "end": "00:13:44,234", "text": "And now that my conscience had been cleared,", "textRu": "И теперь, когда моя совесть очистилась,"}, {"id": 334, "start": "00:13:44,312", "end": "00:13:46,559", "text": "my colon was ready to do the same.", "textRu": "моя толстая кишка была готова сделать то же самое."}, {"id": 335, "start": "00:13:46,792", "end": "00:13:50,252", "text": "Excuse me. I need to use your bathroom!", "textRu": "Прошу прощения. Мне нужно воспользоваться твоей ванной!"}, {"id": 336, "start": "00:13:57,025", "end": "00:13:59,620", "text": "Thank you for letting me sleep in your bed.", "textRu": "Спасибо, что позволил мне поспать в твоей постели."}, {"id": 337, "start": "00:14:00,033", "end": "00:14:02,861", "text": "My father taught me that we must always honor our guests", "textRu": "Мой отец учил меня, что мы всегда должны почтить наших гостей."}, {"id": 338, "start": "00:14:02,939", "end": "00:14:04,891", "text": "and treat them with the utmost courtesy.", "textRu": "и относитесь к ним с предельной вежливостью."}, {"id": 339, "start": "00:14:05,079", "end": "00:14:07,729", "text": "The Vietnamese are a very welcoming people.", "textRu": "Вьетнамцы – очень гостеприимный народ."}, {"id": 340, "start": "00:14:07,986", "end": "00:14:10,854", "text": "Yeah, that hasn't always worked out for us.", "textRu": "Да, у нас это не всегда получалось."}, {"id": 341, "start": "00:14:15,767", "end": "00:14:18,134", "text": "Do you think your dad would ever ask you", "textRu": "Как ты думаешь, твой отец когда-нибудь спросит тебя"}, {"id": 342, "start": "00:14:18,212", "end": "00:14:19,926", "text": "to keep a secret from your mom?", "textRu": "сохранить секрет от мамы?"}, {"id": 343, "start": "00:14:20,004", "end": "00:14:21,025", "text": "Oh, no.", "textRu": "О, нет."}, {"id": 344, "start": "00:14:21,103", "end": "00:14:23,213", "text": "He's so honest, it's annoying.", "textRu": "Он такой честный, что это раздражает."}, {"id": 345, "start": "00:14:24,095", "end": "00:14:25,080", "text": "Enough talking.", "textRu": "Хватит говорить."}, {"id": 346, "start": "00:14:25,158", "end": "00:14:26,478", "text": "Sleep now.", "textRu": "Спи сейчас."}, {"id": 347, "start": "00:14:29,126", "end": "00:14:30,815", "text": "She's just annoying.", "textRu": "Она просто раздражает."}, {"id": 348, "start": "00:14:38,697", "end": "00:14:40,754", "text": "Well, you did it.", "textRu": "Ну, ты сделал это."}, {"id": 349, "start": "00:14:41,905", "end": "00:14:43,776", "text": "How was your first sleepover?", "textRu": "Как прошла ваша первая ночевка?"}, {"id": 350, "start": "00:14:46,677", "end": "00:14:48,449", "text": "They feed you any weird food?", "textRu": "Тебя кормят какой-то странной едой?"}, {"id": 351, "start": "00:14:48,527", "end": "00:14:51,768", "text": "When I was in 'Nam, we ate fish soup for breakfast.", "textRu": "Когда я был во Вьетнаме, мы ели на завтрак уху."}, {"id": 352, "start": "00:14:53,564", "end": "00:14:55,059", "text": "Sheldon, I'm talking to you.", "textRu": "Шелдон, я говорю с тобой."}, {"id": 353, "start": "00:14:55,137", "end": "00:14:57,159", "text": "Well, I'm not talking to you.", "textRu": "Ну, я не с тобой разговариваю."}, {"id": 354, "start": "00:14:57,634", "end": "00:14:59,025", "text": "Okay, what's going on?", "textRu": "Хорошо, что происходит?"}, {"id": 355, "start": "00:14:59,103", "end": "00:15:01,598", "text": "After having my first good night's sleep in a week,", "textRu": "После того, как я впервые за неделю хорошо выспался,"}, {"id": 356, "start": "00:15:01,676", "end": "00:15:03,541", "text": "I woke up with a fresh perspective.", "textRu": "Я проснулся со свежим взглядом."}, {"id": 357, "start": "00:15:03,640", "end": "00:15:05,002", "text": "And that is...?", "textRu": "И это...?"}, {"id": 358, "start": "00:15:05,447", "end": "00:15:07,236", "text": "It was irresponsible of you", "textRu": "Это было безответственно с твоей стороны"}, {"id": 359, "start": "00:15:07,314", "end": "00:15:09,080", "text": "to burden me with that secret.", "textRu": "обременять меня этой тайной."}, {"id": 360, "start": "00:15:09,408", "end": "00:15:10,855", "text": "Sheldon, we've been through this.", "textRu": "Шелдон, мы прошли через это."}, {"id": 361, "start": "00:15:10,933", "end": "00:15:13,174", "text": "Okay. It's... It's complicated.", "textRu": "Хорошо. Это... Это сложно."}, {"id": 362, "start": "00:15:13,345", "end": "00:15:14,931", "text": "While I may not look up to you", "textRu": "Хотя я, возможно, не смотрю на тебя"}, {"id": 363, "start": "00:15:15,009", "end": "00:15:16,613", "text": "from an intellectual standpoint,", "textRu": "с интеллектуальной точки зрения,"}, {"id": 364, "start": "00:15:16,691", "end": "00:15:18,987", "text": "I've always looked up to you as a role model.", "textRu": "Я всегда смотрел на тебя как на образец для подражания."}, {"id": 365, "start": "00:15:22,329", "end": "00:15:24,172", "text": "I can't do that anymore.", "textRu": "Я больше не могу этого делать."}, {"id": 366, "start": "00:15:27,755", "end": "00:15:29,776", "text": "And don't worry... We made a deal.", "textRu": "И не волнуйся... Мы заключили сделку."}, {"id": 367, "start": "00:15:30,009", "end": "00:15:32,174", "text": "I'll continue to keep your secret.", "textRu": "Я буду продолжать хранить твою тайну."}, {"id": 368, "start": "00:15:43,903", "end": "00:15:44,861", "text": "Hey.", "textRu": "Привет."}, {"id": 369, "start": "00:15:44,939", "end": "00:15:45,885", "text": "What's up?", "textRu": "Как дела?"}, {"id": 370, "start": "00:15:45,963", "end": "00:15:48,432", "text": "Um, I need to tell you something.", "textRu": "Эм, мне нужно тебе кое-что сказать."}, {"id": 371, "start": "00:15:48,510", "end": "00:15:49,803", "text": "What did you do?", "textRu": "Что ты сделал?"}, {"id": 372, "start": "00:15:50,684", "end": "00:15:52,685", "text": "When Sheldon was doing our taxes,", "textRu": "Когда Шелдон платил наши налоги,"}, {"id": 373, "start": "00:15:52,763", "end": "00:15:54,189", "text": "he noticed a missing check.", "textRu": "он заметил пропавший чек."}, {"id": 374, "start": "00:15:54,267", "end": "00:15:55,302", "text": "What did you do?", "textRu": "Что ты сделал?"}, {"id": 375, "start": "00:15:55,380", "end": "00:15:57,442", "text": "Before I answer, do you trust me enough", "textRu": "Прежде чем я отвечу, достаточно ли ты мне доверяешь?"}, {"id": 376, "start": "00:15:57,520", "end": "00:15:59,304", "text": "to understand it was for a good reason", "textRu": "понять, что это было по уважительной причине"}, {"id": 377, "start": "00:15:59,382", "end": "00:16:00,982", "text": "and j-just leave it at that?", "textRu": "и п-просто оставить все как есть?"}, {"id": 378, "start": "00:16:05,051", "end": "00:16:06,963", "text": "What did you do?", "textRu": "Что ты сделал?"}, {"id": 379, "start": "00:16:07,091", "end": "00:16:09,132", "text": "It's all your mother's fault. She is a bad person.", "textRu": "Во всем виновата твоя мать. Она плохой человек."}, {"id": 380, "start": "00:16:09,210", "end": "00:16:10,771", "text": "I've been telling you for years.", "textRu": "Я говорил вам уже много лет."}, {"id": 381, "start": "00:16:11,161", "end": "00:16:12,567", "text": "What did you do?", "textRu": "Что ты сделал?"}, {"id": 382, "start": "00:16:12,645", "end": "00:16:14,460", "text": "Okay, now, before I answer that...", "textRu": "Хорошо, прежде чем я отвечу на этот вопрос..."}, {"id": 383, "start": "00:16:14,538", "end": "00:16:15,961", "text": "Just tell me what you did.", "textRu": "Просто скажи мне, что ты сделал."}, {"id": 384, "start": "00:16:16,039", "end": "00:16:17,725", "text": "I got a DWI.", "textRu": "Я получил вождение в нетрезвом состоянии."}, {"id": 385, "start": "00:16:18,005", "end": "00:16:19,057", "text": "Mom!", "textRu": "Мама!"}, {"id": 386, "start": "00:16:19,135", "end": "00:16:20,794", "text": "It's not as bad as it sounds.", "textRu": "Это не так плохо, как кажется."}, {"id": 387, "start": "00:16:20,872", "end": "00:16:23,164", "text": "How is driving drunk not bad?", "textRu": "Чем не плохо водить машину в нетрезвом виде?"}, {"id": 388, "start": "00:16:23,242", "end": "00:16:25,248", "text": "I wasn't exactly driving.", "textRu": "Я был не совсем за рулем."}, {"id": 389, "start": "00:16:25,419", "end": "00:16:27,124", "text": "I don't follow.", "textRu": "Я не следую."}, {"id": 390, "start": "00:16:27,559", "end": "00:16:29,593", "text": "I was at the dog track with Georgie,", "textRu": "Я был на собачьей беговой дорожке с Джорджи,"}, {"id": 391, "start": "00:16:29,671", "end": "00:16:30,842", "text": "and I had a few...", "textRu": "и у меня было несколько..."}, {"id": 392, "start": "00:16:30,920", "end": "00:16:32,013", "text": "Georgie?", "textRu": "Джорджи?"}, {"id": 393, "start": "00:16:32,411", "end": "00:16:33,763", "text": "With God as my witness,", "textRu": "Имея Бога в качестве моего свидетеля,"}, {"id": 394, "start": "00:16:33,841", "end": "00:16:36,389", "text": "I've never been to the dog track in my life.", "textRu": "Я никогда в жизни не был на собачьей беговой дорожке."}, {"id": 395, "start": "00:16:36,669", "end": "00:16:38,148", "text": "She knows.", "textRu": "Она знает."}, {"id": 396, "start": "00:16:38,294", "end": "00:16:39,846", "text": "Oh, I've been there a bunch.", "textRu": "О, я был там много раз."}, {"id": 397, "start": "00:16:39,927", "end": "00:16:42,181", "text": "Will someone please tell me what happened?", "textRu": "Кто-нибудь, пожалуйста, расскажет мне, что произошло?"}, {"id": 398, "start": "00:16:42,411", "end": "00:16:45,525", "text": "Okay, me and Meemaw were in the bar at the track...", "textRu": "Ладно, мы с Мимо были в баре на трассе..."}, {"id": 399, "start": "00:16:45,603", "end": "00:16:47,360", "text": "You took him to a bar?", "textRu": "Ты водил его в бар?"}, {"id": 400, "start": "00:16:47,438", "end": "00:16:48,943", "text": "He wasn't drinking.", "textRu": "Он не пил."}, {"id": 401, "start": "00:16:49,091", "end": "00:16:50,942", "text": "She had a few too many margaritas,", "textRu": "Она выпила слишком много маргариты,"}, {"id": 402, "start": "00:16:51,020", "end": "00:16:52,046", "text": "so I drove us home.", "textRu": "поэтому я отвез нас домой."}, {"id": 403, "start": "00:16:52,124", "end": "00:16:53,730", "text": "But you don't have a license.", "textRu": "Но у вас нет лицензии."}, {"id": 404, "start": "00:16:53,808", "end": "00:16:56,617", "text": "That's why we swapped places after the cop pulled us over.", "textRu": "Вот почему мы поменялись местами после того, как нас остановил полицейский."}, {"id": 405, "start": "00:16:56,695", "end": "00:16:57,887", "text": "Oh, dear Lord.", "textRu": "О, дорогой Господь."}, {"id": 406, "start": "00:16:57,965", "end": "00:16:59,359", "text": "I had nothing to do with this part.", "textRu": "Я не имел никакого отношения к этой части."}, {"id": 407, "start": "00:16:59,437", "end": "00:17:01,247", "text": "- Shut up. - Will do.", "textRu": "- Замолчи. - Сделаю."}, {"id": 408, "start": "00:17:01,653", "end": "00:17:02,935", "text": "I didn't want Georgie", "textRu": "Я не хотел Джорджи"}, {"id": 409, "start": "00:17:03,013", "end": "00:17:04,046", "text": "to get into trouble,", "textRu": "попасть в беду,"}, {"id": 410, "start": "00:17:04,124", "end": "00:17:05,531", "text": "so I got behind the wheel", "textRu": "поэтому я сел за руль"}, {"id": 411, "start": "00:17:05,609", "end": "00:17:07,257", "text": "before the cop walked up.", "textRu": "прежде чем подошел полицейский."}, {"id": 412, "start": "00:17:07,335", "end": "00:17:10,208", "text": "And then I got arrested, and, uh,", "textRu": "А потом меня арестовали, и, ух,"}, {"id": 413, "start": "00:17:10,286", "end": "00:17:11,583", "text": "he bailed me out.", "textRu": "он выручил меня."}, {"id": 414, "start": "00:17:11,661", "end": "00:17:13,913", "text": "So you all thought you should keep this from me?", "textRu": "Итак, вы все решили, что вам следует скрывать это от меня?"}, {"id": 415, "start": "00:17:13,991", "end": "00:17:15,418", "text": "- Absolutely. - 100%.", "textRu": "- Абсолютно. - 100%."}, {"id": 416, "start": "00:17:15,496", "end": "00:17:17,755", "text": "Okay, here's what's gonna happen: you", "textRu": "Хорошо, вот что произойдет: ты"}, {"id": 417, "start": "00:17:17,833", "end": "00:17:19,515", "text": "and you are staying at her house", "textRu": "и ты остаешься у нее дома"}, {"id": 418, "start": "00:17:19,593", "end": "00:17:20,971", "text": "until I say otherwise.", "textRu": "пока я не скажу обратное."}, {"id": 419, "start": "00:17:21,049", "end": "00:17:23,445", "text": "One could argue I was the hero in this story.", "textRu": "Можно утверждать, что я был героем этой истории."}, {"id": 420, "start": "00:17:23,523", "end": "00:17:26,398", "text": "You went gambling and  you drove without a license", "textRu": "Вы играли в азартные игры и водили машину без прав"}, {"id": 421, "start": "00:17:26,476", "end": "00:17:27,916", "text": "and you lied to my face.", "textRu": "и ты солгал мне в лицо."}, {"id": 422, "start": "00:17:27,994", "end": "00:17:29,346", "text": "Heroically.", "textRu": "Героически."}, {"id": 423, "start": "00:17:29,497", "end": "00:17:30,862", "text": "Go.", "textRu": "Идти."}, {"id": 424, "start": "00:17:35,848", "end": "00:17:38,471", "text": "I love everything about this.", "textRu": "Мне нравится все в этом."}, {"id": 425, "start": "00:17:42,578", "end": "00:17:44,445", "text": "I'm guessing you're mad at me.", "textRu": "Я предполагаю, что ты злишься на меня."}, {"id": 426, "start": "00:17:44,523", "end": "00:17:46,193", "text": "Aw, forget about it.", "textRu": "Ой, забудь об этом."}, {"id": 427, "start": "00:17:46,309", "end": "00:17:47,867", "text": "I appreciate you not...", "textRu": "Я ценю тебя, нет..."}, {"id": 428, "start": "00:17:48,106", "end": "00:17:50,037", "text": "ratting me out about the picnic.", "textRu": "выдал меня насчет пикника."}, {"id": 429, "start": "00:17:50,458", "end": "00:17:53,451", "text": "Well, we had a deal.", "textRu": "Ну, у нас была сделка."}, {"id": 430, "start": "00:17:53,598", "end": "00:17:56,906", "text": "Besides, your marriage is already hanging by a thread.", "textRu": "К тому же ваш брак уже висит на волоске."}, {"id": 431, "start": "00:17:56,984", "end": "00:17:58,662", "text": "It is dangling there.", "textRu": "Оно там висит."}, {"id": 432, "start": "00:17:59,434", "end": "00:18:01,847", "text": "All right, well, I'm gonna turn in.", "textRu": "Хорошо, я собираюсь сдаться."}, {"id": 433, "start": "00:18:02,121", "end": "00:18:03,418", "text": "Mmm.", "textRu": "М-м-м."}, {"id": 434, "start": "00:18:03,685", "end": "00:18:05,107", "text": "Good night.", "textRu": "Спокойной ночи."}, {"id": 435, "start": "00:18:06,243", "end": "00:18:07,739", "text": "Night!", "textRu": "Ночь!"}, {"id": 436, "start": "00:18:13,864", "end": "00:18:14,880", "text": "Hello?", "textRu": "Привет?"}, {"id": 437, "start": "00:18:14,958", "end": "00:18:16,195", "text": "So, get a load of this.", "textRu": "Итак, возьмите эту порцию."}, {"id": 438, "start": "00:18:16,273", "end": "00:18:18,849", "text": "Last church picnic, your husband", "textRu": "Последний церковный пикник, твой муж"}, {"id": 439, "start": "00:18:18,927", "end": "00:18:20,513", "text": "snuck in a six-pack,", "textRu": "пробрался в упаковке из шести штук,"}, {"id": 440, "start": "00:18:20,591", "end": "00:18:22,106", "text": "polished off the whole thing,", "textRu": "отполировал все это дело,"}, {"id": 441, "start": "00:18:22,184", "end": "00:18:24,453", "text": "then went to wait in line for the bathroom...", "textRu": "потом пошел ждать в очереди в туалет..."}, {"id": 442, "start": "00:18:24,531", "end": "00:18:25,536", "text": "Hey.", "textRu": "Привет."}, {"id": 443, "start": "00:18:25,653", "end": "00:18:27,302", "text": "You got an extra toothbrush?", "textRu": "У тебя есть дополнительная зубная щетка?"}, {"id": 444, "start": "00:18:27,380", "end": "00:18:28,898", "text": "Under the sink, darlin'.", "textRu": "Под раковиной, дорогая."}, {"id": 445, "start": "00:18:28,976", "end": "00:18:29,958", "text": "Thanks.", "textRu": "Спасибо."}, {"id": 446, "start": "00:18:30,036", "end": "00:18:31,514", "text": "You got it.", "textRu": "Вы поняли."}, {"id": 447, "start": "00:18:32,794", "end": "00:18:36,805", "text": "So then the big gorilla decides he doesn't want to wait in line,", "textRu": "И тогда большая горилла решает, что не хочет стоять в очереди."}, {"id": 448, "start": "00:18:36,883", "end": "00:18:39,892", "text": "so he stumbles over to the church vegetable garden", "textRu": "поэтому он наткнулся на церковный огород"}, {"id": 449, "start": "00:18:39,970", "end": "00:18:44,403", "text": "and proceeds to irrigate the whole damn thing.", "textRu": "и приступает к орошению всей этой чертовой штуки."}, {"id": 450, "start": "00:18:44,481", "end": "00:18:46,624", "text": "I've eaten those vegetables.", "textRu": "Я ел эти овощи."}, {"id": 451, "start": "00:18:46,702", "end": "00:18:48,529", "text": "Sweet dreams.", "textRu": "Сладкие сны."}]};
